import{_ as s,C as a,c as r,o as i,a3 as e,G as n}from"./chunks/framework.Dokpd4od.js";const k=JSON.parse('{"title":"Stock moves and lots","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/operations/stock-moves-and-lots.md","filePath":"master/supply-chain/inventories/operations/stock-moves-and-lots.md","lastUpdated":1793074831000}'),l={name:"master/supply-chain/inventories/operations/stock-moves-and-lots.md"};function g(d,t,c,h,p,u){const o=a("ImagePopup");return i(),r("div",null,[t[0]||(t[0]=e('<h1 id="stock-moves-and-lots" tabindex="-1">Stock moves and lots <a class="header-anchor" href="#stock-moves-and-lots" aria-label="Permalink to &quot;Stock moves and lots&quot;">​</a></h1><p>Each line in a transfer is a stock move. A move says &quot;this product, this quantity&quot;. The move can be split into several lines when goods come from or go to different places, lots or packages. The <strong>Manage Stock Moves</strong> window is where you do that split.</p><blockquote><p><strong>In simple words:</strong> The Operations table says how many you expect. <strong>Manage Stock Moves</strong> says exactly where each unit comes from, goes to and which lot it carries.</p></blockquote><p>Open any transfer, click the <strong>Edit</strong> tab of the <strong>View</strong> / <strong>Edit</strong> / <strong>Moves</strong> switcher and go to the <strong>Operations</strong> tab.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><ul><li>Lot and serial fields need <strong>Lots &amp; Serial Numbers</strong> on in <code>Inventory → Settings → Manage Traceability</code>.</li><li>The package field needs <strong>Packages</strong> on in <code>Inventory → Settings → Manage Operations</code>.</li><li><strong>Pick From</strong> and <strong>Store To</strong> need <strong>Locations</strong> on in <code>Inventory → Settings → Manage Warehouses</code>.</li></ul><p>See <a href="./../tracking/lots-and-serial-numbers.html">Lots and serial numbers</a> and <a href="./../tracking/packages.html">Packages</a>.</p><h2 id="the-operations-table" tabindex="-1">The Operations table <a class="header-anchor" href="#the-operations-table" aria-label="Permalink to &quot;The Operations table&quot;">​</a></h2><p>Columns: <strong>Product</strong>, <strong>Packaging</strong>, <strong>Demand</strong>, <strong>Quantity</strong>, <strong>Unit</strong> and <strong>Picked</strong>.</p><ul><li><strong>Demand</strong> is what you plan to move.</li><li><strong>Quantity</strong> is what you actually move.</li><li><strong>Picked</strong> is a toggle switch. Turn it on when the line is physically done.</li></ul>',10)),n(o,{src:"/images1/inventory/mv_operations_table.png",alt:"Operations table with SSD 512GB demand 15 quantity 15 and the Picked toggle switched on"}),t[1]||(t[1]=e('<h2 id="open-manage-stock-moves" tabindex="-1">Open Manage Stock Moves <a class="header-anchor" href="#open-manage-stock-moves" aria-label="Permalink to &quot;Open Manage Stock Moves&quot;">​</a></h2><ol><li>Open the <strong>Edit</strong> tab of the transfer.</li><li>On the product line, click the small list icon next to <strong>Quantity</strong>. Its tooltip reads <strong>Manage Stock Moves</strong>. It is an icon, not a button.</li><li>The window <strong>Manage Stock Moves</strong> opens with a list called <strong>Lines</strong>.</li></ol>',2)),n(o,{src:"/images1/inventory/mv_manage_modal.png",alt:"Manage Stock Moves window for Smart LED Desk Lamp with Store To WH/Input and quantity 10, with the Add Line, Save and Cancel buttons"}),t[2]||(t[2]=e('<h3 id="fields-in-each-line" tabindex="-1">Fields in each line <a class="header-anchor" href="#fields-in-each-line" aria-label="Permalink to &quot;Fields in each line&quot;">​</a></h3><p>On a receipt with a product that has no tracking, the columns are <strong>Store To</strong>, <strong>Destination Package</strong> and <strong>Quantity</strong>. There is no <strong>Pick From</strong> column and no lot field.</p><ul><li><strong><em>Store To:</em></strong> Required. Where the goods end up. For receipts the default is <strong>WH/Input</strong>.</li><li><strong><em>Pick From:</em></strong> Where the goods are taken from. Shown on deliveries and internal moves, not on receipts.</li><li><strong><em>Lot/Serial Number:</em></strong> Shown for products that track lots or serial numbers. It is the first column. Click the <strong>+</strong> next to the field to create a lot.</li><li><strong>Destination Package:</strong> The package the goods go into. It is a searchable select with a <strong>+</strong> button. It lists existing packages only.</li><li><strong><em>Quantity:</em></strong> Required. Shown with the unit.</li></ul><p>Click <strong>Add Line</strong> to split a move. Example: 15 SSD split into 10 for <strong>WH/Input</strong> and 5 for a second shelf. Click <strong>Save</strong> when done, or <strong>Cancel</strong> to close the window without changes.</p><h2 id="lot-and-serial-wizards" tabindex="-1">Lot and serial wizards <a class="header-anchor" href="#lot-and-serial-wizards" aria-label="Permalink to &quot;Lot and serial wizards&quot;">​</a></h2><p>For tracked products, two links sit in the window header: <strong>Generate Serials/Lots</strong> and <strong>Import Serials/Lots</strong>.</p><h3 id="generate-serials-lots" tabindex="-1">Generate Serials/Lots <a class="header-anchor" href="#generate-serials-lots" aria-label="Permalink to &quot;Generate Serials/Lots&quot;">​</a></h3><p>Use it when the numbers follow a pattern.</p><ol><li>Click <strong>Generate Serials/Lots</strong>. The window <strong>Generate Serials/Lots</strong> opens.</li><li>Fill <strong>First Lot Number</strong>, for example <strong>LOT0001</strong>. It is required.</li><li>Check <strong>Quantity per Lot</strong> and <strong>Quantity Received</strong>. Both are prefilled, and <strong>Quantity Received</strong> is required.</li><li>Turn on the <strong>Keep current lines</strong> toggle if you want to keep existing lines.</li><li>Click <strong>Submit</strong>.</li></ol><p>Aureus fills the line with the lot, the quantity and the transfer unit. It does not save yet. Click <strong>Save</strong> in the <strong>Manage Stock Moves</strong> window.</p><h3 id="import-serials-lots" tabindex="-1">Import Serials/Lots <a class="header-anchor" href="#import-serials-lots" aria-label="Permalink to &quot;Import Serials/Lots&quot;">​</a></h3><p>Use it when you have a list, such as a scanner export.</p><ol><li>Click <strong>Import Serials/Lots</strong>.</li><li>The window <strong>Import Serials/Lots</strong> opens. Paste the numbers into <strong>Lot/Serial Numbers</strong>. It is required, and the helper text reads &quot;One lot/serial number per line.&quot;</li><li>Turn on the <strong>Keep current lines</strong> toggle if needed.</li><li>Click <strong>Submit</strong>, then <strong>Save</strong> in the <strong>Manage Stock Moves</strong> window.</li></ol><h2 id="validation-warnings" tabindex="-1">Validation warnings <a class="header-anchor" href="#validation-warnings" aria-label="Permalink to &quot;Validation warnings&quot;">​</a></h2><p>Aureus checks the lines on <strong>Validate</strong>:</p><ul><li><strong>Supply Lot/Serial Number:</strong> a tracked product has no number.</li><li><strong>Serial Number Already Assigned:</strong> the serial is used elsewhere.</li><li><strong>Can not move same package content:</strong> a package would move to its own place.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Serial numbers are unique. Use one line per serial with a quantity of 1.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./receipts.html">Receipts</a></li><li><a href="./../tracking/lots-and-serial-numbers.html">Lots and serial numbers</a></li><li><a href="./../tracking/packages.html">Packages</a></li><li><a href="./print-documents.html">Print documents</a></li></ul>',19))])}const S=s(l,[["render",g]]);export{k as __pageData,S as default};
